n  // LiteSpeed/global webserver pressure.\n  liteSpeedConnections Int @default(0) @map(\"litespeed_connections\")\n\n  // Disk I/O.\n  diskReadBytesPerSecond  BigInt @map(\"disk_read_bytes_per_second\")\n  diskWriteBytesPerSecond BigInt @map(\"disk_write_bytes_per_second\")\n  diskIops                Int    @map(\"disk_iops\")\n\n  // Coarse total storage. Detailed per-mount data is in VpsFilesystemMetric.\n  storageTotalMB     Int @map(\"storage_total_mb\")\n  storageAvailableMB Int @map(\"storage_available_mb\")\n\n  // Coarse total network. Detailed per-interface data is in VpsNetworkInterfaceMetric.\n  networkRxBytesPerSecond BigInt @map(\"network_rx_bytes_per_second\")\n  networkTxBytesPerSecond BigInt @map(\"network_tx_bytes_per_second\")\n\n  // Ingestion timestamp for backend debugging. This is not the metric bucket time.\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  vpsNode VpsNode @relation(fields: [vpsNodeId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, vpsNodeId])\n  @@index([vpsNodeId, recordedAt(sort: Desc)])\n  @@map(\"vps_metrics\")\n}\n\nmodel WebMetric {\n  recordedAt DateTime @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  vpsNodeId  String   @map(\"vps_node_id\") @db.Uuid\n  websiteId  String   @map(\"website_id\") @db.Uuid\n\n  // LiteSpeed virtual-host traffic pressure.\n  concurrentRequests Int @default(0) @map(\"concurrent_requests\")\n  requestRate        Int @default(0) @map(\"request_rate\")\n\n  // Optional richer traffic data when the agent can provide it.\n  activeConnections  Int?    @map(\"active_connections\")\n  processingRequests Int?    @map(\"processing_requests\")\n  bytesInPerSecond   BigInt? @map(\"bytes_in_per_second\")\n  bytesOutPerSecond  BigInt? @map(\"bytes_out_per_second\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  vpsNode VpsNode @relation(fields: [vpsNodeId], references: [id], onDelete: Cascade)\n  website Website @relation(fields: [websiteId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, websiteId])\n  @@index([websiteId, recordedAt(sort: Desc)])\n  @@index([vpsNodeId, recordedAt(sort: Desc)])\n  @@map(\"web_metrics\")\n}\n\nmodel WebsiteProbeMetric {\n  recordedAt  DateTime           @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  websiteId   String             @map(\"website_id\") @db.Uuid\n  probeSource WebsiteProbeSource @default(AGENT) @map(\"probe_source\")\n\n  isUp           Boolean @map(\"is_up\")\n  statusCode     Int?    @map(\"status_code\")\n  responseTimeMs Int?    @map(\"response_time_ms\")\n  ttfbMs         Int?    @map(\"ttfb_ms\")\n\n  // Useful for explaining problems to non-technical website owners.\n  errorMessage String? @map(\"error_message\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  website Website @relation(fields: [websiteId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, websiteId, probeSource])\n  @@index([websiteId, recordedAt(sort: Desc)])\n  @@index([isUp, recordedAt(sort: Desc)])\n  @@map(\"website_probe_metrics\")\n}\n\nmodel WebsiteSslMetric {\n  recordedAt DateTime @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  websiteId  String   @map(\"website_id\") @db.Uuid\n\n  isValid       Boolean   @map(\"is_valid\")\n  validFrom     DateTime? @map(\"valid_from\") @db.Timestamptz(6)\n  validTo       DateTime? @map(\"valid_to\") @db.Timestamptz(6)\n  daysRemaining Int?      @map(\"days_remaining\")\n\n  issuer        String?\n  subject       String?\n  serialNumber  String? @map(\"serial_number\")\n  statusMessage String? @map(\"status_message\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  website Website @relation(fields: [websiteId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, websiteId])\n  @@index([websiteId, recordedAt(sort: Desc)])\n  @@index([isValid, recordedAt(sort: Desc)])\n  @@map(\"website_ssl_metrics\")\n}\n\nmodel VpsFilesystemMetric {\n  recordedAt DateTime @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  vpsNodeId  String   @map(\"vps_node_id\") @db.Uuid\n\n  mountPoint   String  @map(\"mount_point\")\n  filesystem   String?\n  totalMB      Int     @map(\"total_mb\")\n  usedMB       Int     @map(\"used_mb\")\n  availableMB  Int     @map(\"available_mb\")\n  usagePercent Float   @map(\"usage_percent\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  vpsNode VpsNode @relation(fields: [vpsNodeId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, vpsNodeId, mountPoint])\n  @@index([vpsNodeId, recordedAt(sort: Desc)])\n  @@index([vpsNodeId, mountPoint, recordedAt(sort: Desc)])\n  @@map(\"vps_filesystem_metrics\")\n}\n\nmodel VpsNetworkInterfaceMetric {\n  recordedAt DateTime @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  vpsNodeId  String   @map(\"vps_node_id\") @db.Uuid\n\n  interfaceName String @map(\"interface_name\")\n\n  rxBytesPerSecond BigInt @map(\"rx_bytes_per_second\")\n  txBytesPerSecond BigInt @map(\"tx_bytes_per_second\")\n\n  rxPacketsPerSecond BigInt? @map(\"rx_packets_per_second\")\n  txPacketsPerSecond BigInt? @map(\"tx_packets_per_second\")\n\n  rxErrors Int @default(0) @map(\"rx_errors\")\n  txErrors Int @default(0) @map(\"tx_errors\")\n  rxDrops  Int @default(0) @map(\"rx_drops\")\n  txDrops  Int @default(0) @map(\"tx_drops\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  vpsNode VpsNode @relation(fields: [vpsNodeId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, vpsNodeId, interfaceName])\n  @@index([vpsNodeId, recordedAt(sort: Desc)])\n  @@index([vpsNodeId, interfaceName, recordedAt(sort: Desc)])\n  @@map(\"vps_network_interface_metrics\")\n}\n\nmodel VpsServiceMetric {\n  recordedAt DateTime @default(now()) @map(\"recorded_at\") @db.Timestamptz(6)\n  vpsNodeId  String   @map(\"vps_node_id\") @db.Uuid\n\n  serviceName String  @map(\"service_name\")\n  isActive    Boolean @map(\"is_active\")\n  status      String?\n  memoryMB    Int?    @map(\"memory_mb\")\n\n  ingestedAt DateTime @default(now()) @map(\"ingested_at\") @db.Timestamptz(6)\n\n  vpsNode VpsNode @relation(fields: [vpsNodeId], references: [id], onDelete: Cascade)\n\n  @@id([recordedAt, vpsNodeId, serviceName])\n  @@index([vpsNodeId, recordedAt(sort: Desc)])\n  @@index([vpsNodeId, serviceName, recordedAt(sort: Desc)])\n  @@index([isActive, recordedAt(sort: Desc)])\n  @@map(\"vps_service_metrics\")\n}\n\n// -----------------------------------------------------------------------------\n// CURRENT-STATE / BUSINESS TABLES\n// -----------------------------------------------------------------------------\n\nmodel SSLCertificate {\n  id        String @id @default(uuid()) @db.Uuid\n  websiteId String @unique @map(\"website_id\") @db.Uuid\n\n  // Latest SSL state for dashboard cards.\n  issuer    String?\n  subject   String?\n  validFrom DateTime? @map(\"valid_from\") @db.Timestamptz(6)\n  validTo   DateTime? @map(\"valid_to\") @db.Timestamptz(6)\n  isValid   Boolean   @default(true) @map(\"is_valid\")\n\n  // Technical telemetry for admin debugging and automation.\n  serialNumber    String? @map(\"serial_number\")\n  isAutoRenewable Boolean @default(true) @map(\"is_auto_renewable\")\n  statusMessage   String? @map(\"status_message\")\n\n  website Website @relation(fields: [websiteId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([validTo])\n  @@index([isValid])\n  @@map(\"ssl_certificates\")\n}\n\nmodel Alert {\n  id String @id @default(uuid()) @db.Uuid\n\n  websiteId String? @map(\"website_id\") @db.Uuid\n  vpsNodeId String? @map(\"vps_node_id\") @db.Uuid\n  serverId  String? @map(\"server_id\") @db.Uuid\n\n  title   String\n  message String\n\n  severity AlertSeverity\n  status   AlertStatus   @default(ACTIVE)\n\n  startedAt      DateTime  @default(now()) @map(\"started_at\") @db.Timestamptz(6)\n  acknowledgedAt DateTime? @map(\"acknowledged_at\") @db.Timestamptz(6)\n  resolvedAt     DateTime? @map(\"resolved_at\") @db.Timestamptz(6)\n  suppressedAt   DateTime? @map(\"suppressed_at\") @db.Timestamptz(6)\n\n  metadata Json?\n\n  website Website? @relation(fields: [websiteId], references: [id], onDelete: Cascade)\n  vpsNode VpsNode? @relation(fields: [vpsNodeId], references: [id], onDelete: SetNull)\n  server  Server?  @relation(fields: [serverId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([websiteId])\n  @@index([vpsNodeId])\n  @@index([serverId])\n  @@index([status])\n  @@index([severity])\n  @@index([startedAt])\n  @@index([websiteId, startedAt(sort: Desc)])\n  @@index([vpsNodeId, startedAt(sort: Desc)])\n  @@map(\"alerts\")\n}\n\n/// One outstanding OTP challenge per delivery target. The plaintext code is\n/// never persisted: only its bcrypt digest is stored, so a database read\n/// cannot recover a usable code.\nmodel Otp {\n  id                String      @id @default(uuid()) @db.Uuid\n  otpHash           String      @map(\"otp_hash\")\n  phoneNumber       String?     @unique @map(\"phone_number\")\n  expiredTime       DateTime    @map(\"expired_time\") @db.Timestamptz(6)\n  identifier        String?     @unique\n  lastRequestedTime DateTime?   @map(\"last_requested_time\") @db.Timestamptz(6)\n  context           OtpContext? @default(LOGIN)\n\n  /// Failed verification attempts against the current code. Reset on reissue.\n  attemptCount Int       @default(0) @map(\"attempt_count\")\n  /// Set once the code verifies successfully; blocks replay of the same code.\n  consumedAt   DateTime? @map(\"consumed_at\") @db.Timestamptz(6)\n\n  /// Issue requests inside the current per-target window, for abuse limiting.\n  requestCount           Int       @default(0) @map(\"request_count\")\n  requestWindowStartedAt DateTime? @map(\"request_window_started_at\") @db.Timestamptz(6)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"otps\")\n}\n\nmodel Plan {\n  id            String  @id @default(uuid()) @db.Uuid\n  code          String  @unique\n  nameFa        String  @map(\"name_fa\")\n  nameEn        String  @map(\"name_en\")\n  descriptionFa String? @map(\"description_fa\")\n  descriptionEn String? @map(\"description_en\")\n  isPublished   Boolean @default(false) @map(\"is_published\")\n  sortOrder     Int     @default(0) @map(\"sort_order\")\n  metadata      Json?\n\n  websites     Website[]\n  planRequests PlanRequest[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([isPublished, sortOrder])\n  @@map(\"plans\")\n}\n\nmodel PlanRequest {\n  id              String            @id @default(uuid()) @db.Uuid\n  planId          String            @map(\"plan_id\") @db.Uuid\n  status          PlanRequestStatus @default(SUBMITTED)\n  contactName     String            @map(\"contact_name\")\n  contactPhone    String?           @map(\"contact_phone\")\n  contactEmail    String?           @map(\"contact_email\")\n  websiteDomain   String?           @map(\"website_domain\")\n  notes           String?\n  tenantId        String?           @map(\"tenant_id\") @db.Uuid\n  linkedUserId    String?           @map(\"linked_user_id\") @db.Uuid\n  websiteId       String?           @map(\"website_id\") @db.Uuid\n  createdByUserId String?           @map(\"created_by_user_id\") @db.Uuid\n  enabledAt       DateTime?         @map(\"enabled_at\") @db.Timestamptz(6)\n  declinedAt      DateTime?         @map(\"declined_at\") @db.Timestamptz(6)\n  declineReason   String?           @map(\"decline_reason\")\n  idempotencyKey  String?           @unique @map(\"idempotency_key\")\n\n  plan          Plan     @relation(fields: [planId], references: [id], onDelete: Restrict)\n  tenant        Tenant?  @relation(fields: [tenantId], references: [id], onDelete: SetNull)\n  linkedUser    User?    @relation(\"PlanRequestLinkedUser\", fields: [linkedUserId], references: [id], onDelete: SetNull)\n  website       Website? @relation(fields: [websiteId], references: [id], onDelete: SetNull)\n  createdByUser User?    @relation(\"PlanRequestCreatedBy\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([status])\n  @@index([planId])\n  @@index([tenantId])\n  @@index([websiteId])\n  @@map(\"plan_requests\")\n}\n\nmodel ServiceCatalogItem {\n  id            String  @id @default(uuid()) @db.Uuid\n  code          String  @unique\n  nameFa        String  @map(\"name_fa\")\n  nameEn        String  @map(\"name_en\")\n  descriptionFa String? @map(\"description_fa\")\n  descriptionEn String? @map(\"description_en\")\n  isPublished   Boolean @default(false) @map(\"is_published\")\n  sortOrder     Int     @default(0) @map(\"sort_order\")\n\n  requests ComplementaryServiceRequest[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([isPublished, sortOrder])\n  @@map(\"service_catalog_items\")\n}\n\nmodel ComplementaryServiceRequest {\n  id                      String                               @id @default(uuid()) @db.Uuid\n  catalogItemId           String                               @map(\"catalog_item_id\") @db.Uuid\n  status                  ComplementaryRequestStatus           @default(SUBMITTED)\n  contactName             String                               @map(\"contact_name\")\n  contactPhone            String?                              @map(\"contact_phone\")\n  contactEmail            String?                              @map(\"contact_email\")\n  details                 String?\n  title                   String?\n  engagementPreference    ComplementaryEngagementPreference?   @map(\"engagement_preference\")\n  scope                   Json?\n  tenantId                String?                              @map(\"tenant_id\") @db.Uuid\n  websiteId               String?                              @map(\"website_id\") @db.Uuid\n  websiteDomain           String?                              @map(\"website_domain\")\n  websiteTargetType       ComplementaryWebsiteTargetType?      @map(\"website_target_type\")\n  websiteCoverageSnapshot WebsiteManagementCoverage?           @map(\"website_coverage_snapshot\")\n  websiteResolutionState  ComplementaryWebsiteResolutionState? @map(\"website_resolution_state\")\n  authorizationState      ComplementaryAuthorizationState?     @map(\"authorization_state\")\n  createdByUserId         String?                              @map(\"created_by_user_id\") @db.Uuid\n  withdrawnAt             DateTime?                            @map(\"withdrawn_at\") @db.Timestamptz(6)\n  acceptedAt              DateTime?                            @map(\"accepted_at\") @db.Timestamptz(6)\n\n  catalogItem   ServiceCatalogItem @relation(fields: [catalogItemId], references: [id], onDelete: Restrict)\n  tenant        Tenant?            @relation(fields: [tenantId], references: [id], onDelete: SetNull)\n  website       Website?           @relation(fields: [websiteId], references: [id], onDelete: SetNull)\n  createdByUser User?              @relation(\"ComplementaryRequestCreatedBy\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  quotations  ServiceQuotation[]\n  assignments ServiceAssignment[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([status])\n  @@index([catalogItemId])\n  @@index([tenantId])\n  @@index([createdByUserId])\n  @@index([websiteDomain])\n  @@map(\"complementary_service_requests\")\n}\n\nmodel ServiceQuotation {\n  id         String    @id @default(uuid()) @db.Uuid\n  requestId  String    @map(\"request_id\") @db.Uuid\n  amount     Decimal   @db.Decimal(12, 2)\n  currency   String    @default(\"IRR\")\n  notes      String?\n  validUntil DateTime? @map(\"valid_until\") @db.Timestamptz(6)\n\n  request ComplementaryServiceRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([requestId])\n  @@map(\"service_quotations\")\n}\n\nmodel ServiceAssignment {\n  id                 String                           @id @default(uuid()) @db.Uuid\n  requestId          String                           @map(\"request_id\") @db.Uuid\n  assigneeNote       String?                          @map(\"assignee_note\")\n  startedAt          DateTime?                        @map(\"started_at\") @db.Timestamptz(6)\n  completedAt        DateTime?                        @map(\"completed_at\") @db.Timestamptz(6)\n  authorizationState ComplementaryAuthorizationState? @map(\"authorization_state\")\n\n  request      ComplementaryServiceRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  usageRecords ServiceUsage[]\n  deliverables ServiceDeliverable[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([requestId])\n  @@map(\"service_assignments\")\n}\n\nmodel ServiceUsage {\n  id           String   @id @default(uuid()) @db.Uuid\n  assignmentId String   @map(\"assignment_